use vstd::prelude::*;

verus! {

spec fn rev_seq(s: Seq<i32>) -> Seq<i32> {
    s.reverse()
}

fn reverse(a: &Vec<i32>) -> (result: Vec<i32>)
    ensures
        result@ == rev_seq(a@),
        result@.len() == a@.len(),
{
    let n = a.len();
    let mut result = Vec::with_capacity(n);

    for i in (0..n).rev()
        invariant
            n == a.len(),
            // how many elements already pushed:
            result@.len() == (n - 1 - i) as nat,
            // pushed prefix equals the corresponding prefix of the reversed input
            result@ == rev_seq(a@).subrange(0, (n - 1 - i) as nat),
        decreases i,
    {
        // safe indexing
        assert(i < a.len());

        result.push(a[i]);

        // after pushing, the result matches one more element of the reversed sequence
        assert(result@ == rev_seq(a@).subrange(0, (n - i) as nat));
    }

    result
}

} // verus!

